// ❌ OLD: Manually threading the requestId (or user, or trace id)
// through every function. Every helper, service, and database call
// must accept and forward it. Add a new piece of context and you edit
// every signature. Miss one hop and logs/errors lose the correlation.
async function handler(req, res) {
  const requestId = req.headers['x-request-id'];
  await step1(requestId); // ❌ OLD
  await step2(requestId); // ❌ OLD
  await db.save({ id: requestId, ... }); // ❌ OLD: every layer polluted
}

async function step1(requestId) {
  log.info({ requestId }, 'step1'); // ❌ OLD: only works if passed
}

const { AsyncLocalStorage } = require('node:async_hooks');
const als = new AsyncLocalStorage(); // ✅ NEW: context carrier

http.createServer((req, res) => {
  const store = { requestId: req.headers['x-request-id'] ?? crypto.randomUUID() };
  // ✅ NEW: scope the context to this request's entire async tree
  als.run(store, async () => {
    await step1(); // ✅ NEW: no params — context is ambient
    await step2();
    res.end('ok');
  });
}).listen(3000);

async function step1() {
  log.info({ requestId: als.getStore().requestId }, 'step1'); // ✅ NEW
}

async function step2() {
  const { requestId } = als.getStore(); // ✅ NEW: follows across awaits
  await db.save({ id: requestId });
}

// Every await hop — timers, promises, streams, events — keeps the
// store, so a logger helper can call als.getStore() anywhere.
